    {
        if (pInfo == 0) return HR(0x80004003);
        pInfo->pFilter = m_pFilter;
        if (m_pFilter) {
            m_pFilter->AddRef();
        }
        if (m_pName) {
            lstrcpynW(pInfo->achName, m_pName, sizeof(pInfo->achName) / sizeof(WCHAR));
        } else {
