        return VFW_E_INVALID_DIRECTION;
    }
    return 0;
}

HRESULT CBaseOutputPin::CheckConnect(IPin* pPin)
{
    HRESULT hr = CBasePin::CheckConnect(pPin);
    if (hr < 0) {
        return hr;
