    IMemAllocator* m_pAllocator; IMemInputPin* m_pInputPin; BOOL m_stopped; HRESULT hrDecide; IMemInputPin* seenPin;
    CBaseOutputPin() : m_pAllocator(0), m_pInputPin(0), m_stopped(1), hrDecide(0), seenPin(0) {}
